'use strict';
(function(){
 const steps=[
  {title:'Elegí qué querés lograr',pose:'green',intro:'Tu rover necesita una prioridad. Las dos opciones son válidas.',items:['Elegí explorar con energía solar o enviar noticias a la Tierra.','Leé el consejo de Félicette para conocer qué cambia.','Tocá Continuar y preparemos el lugar.'],goal:'Al terminar tendrás un objetivo para comparar tus próximas decisiones.'},
  {title:'Encontrá un lugar para tu rover',pose:'terrain',intro:'La Luna completa te ubica. Las tarjetas comparan tres lugares del terreno real.',items:['Girá la Luna y compará las horas de luz y Tierra visible de cada tarjeta.','Acercate al relieve para explorar alturas y pendientes.','Elegí un sitio según tu objetivo; Félicette explica si algo necesita cambiar.'],goal:'El verde es una pista de pendiente, no una garantía de aterrizaje.'},
  {title:'Descubrí cuándo hay luz y contacto',pose:'comms',intro:'Podés mirar el mismo momento desde el rover, desde arriba o con la Luna de perfil.',items:['Elegí una fecha y tocá Explorar esta fecha.','Mové el tiempo y cambiá de vista: observá cuándo el Sol ilumina el panel o queda oculto.','Marcá horarios, pedí pistas y probá tu plan. Félicette explica qué pasó.'],goal:'No hace falta acertar de entrada. Las pistas y los reintentos forman parte del juego.'},
  {title:'Prepará la energía para seguir',pose:'energy',intro:'El panel genera energía y la batería guarda una parte para los momentos sin generación.',items:['Elegí la capacidad de batería y cómo se orienta el panel.','Mirá la energía que genera el panel y si queda consumo sin cubrir.','Probá otra combinación si falta energía; Félicette puede proponerte un rescate.'],goal:'Una batería más grande almacena más: no crea luz ni energía por sí sola.'},
  {title:'Buscá el camino hacia la Tierra',pose:'comms',intro:'Para mandar fotos, la Tierra tiene que superar el horizonte del rover.',items:['Probá la altura de la antena y observá si cambian las ventanas.','Decidí si podés guardar datos para enviarlos después o necesitás contacto continuo.','Revisá los cortes que aparecen: Félicette te explica cómo ajustar tu estrategia.'],goal:'Tierra visible es una oportunidad geométrica; todavía falta validar el enlace de radio.'},
  {title:'Uní las decisiones de tu aventura',pose:'green',intro:'El resumen aparece primero para que puedas revisar tu plan sin buscar al final.',items:['Leé el resumen y volvé a una decisión si querés cambiar algo.','Probá la misión para ver su cierre con Félicette.','Descargá tu plan o abrí el laboratorio para investigar más.'],goal:'Aprender a comparar es el objetivo. Completar el recorrido no certifica una misión real.'}
 ];
 const seen=new Set(),bar=document.createElement('div');bar.id='missionStepGuideBar';bar.className='mission-step-guide-bar';bar.hidden=true;bar.innerHTML='<button type="button" id="openMissionStepGuide"><span>✦ TU GUÍA DE ESTA ETAPA</span><b>¿Qué tengo que hacer?</b><span aria-hidden="true">↗</span></button>';document.getElementById('gameContent').before(bar);
 const dialog=document.createElement('dialog');dialog.id='missionStepGuideDialog';dialog.className='mission-step-guide-dialog';dialog.setAttribute('aria-labelledby','missionStepGuideTitle');dialog.innerHTML='<button type="button" class="step-guide-close" aria-label="Cerrar guía">✕</button><div class="step-guide-layout"><img alt="Félicette te explica esta etapa"><div><span class="eyebrow" id="missionStepGuideKicker"></span><h2 id="missionStepGuideTitle"></h2><p id="missionStepGuideIntro"></p><ol></ol><p class="step-guide-goal"></p><button type="button" class="primary" id="startMissionStep">¡Entendido, vamos! →</button></div></div>';document.body.append(dialog);
 function open(){const i=Math.min(5,mission.step),s=steps[i];dialog.querySelector('img').src=`assets/felicette-${s.pose}.png`;document.getElementById('missionStepGuideKicker').textContent=`ANTES DE EMPEZAR · DECISIÓN ${i+1} DE 6`;document.getElementById('missionStepGuideTitle').textContent=s.title;document.getElementById('missionStepGuideIntro').textContent=s.intro;const list=dialog.querySelector('ol');list.replaceChildren(...s.items.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));dialog.querySelector('.step-guide-goal').textContent=s.goal;window.dispatchEvent(new Event('lunar-guide-open'));if(!dialog.open)dialog.showModal();}
 document.getElementById('openMissionStepGuide').onclick=open;dialog.querySelector('.step-guide-close').onclick=()=>dialog.close();document.getElementById('startMissionStep').onclick=()=>dialog.close();
 const render=renderMission;renderMission=function(...args){render.apply(this,args);bar.hidden=!journeyStarted||document.getElementById('publicMission').hidden;if(bar.hidden){if(dialog.open)dialog.close();return;}const i=Math.min(5,mission.step);if(!seen.has(i)){seen.add(i);if(!document.querySelector('dialog[open]'))open();}};
 const restart=document.getElementById('restartMission').onclick;document.getElementById('restartMission').onclick=()=>{seen.clear();if(dialog.open)dialog.close();restart();};window.addEventListener('hashchange',()=>{if(location.hash!=='#mission'&&dialog.open)dialog.close();});
 if(journeyStarted)renderMission();
})();
